{"version":3,"sources":["../scss/publicationSlug.scss","publicationSlug.css","../scss/_mixins.scss","../scss/_variables.scss"],"names":[],"mappings":"AAGA;EACE,gBAAA;ACFF;;ADKA;EENI,uCAAA;EACA,gBFMkC;EELlC,kBAAA;EACA,YCHW;EDIX,eFG4B;EAC9B,mBAAA;ACEF;;ADCA;EEXI,uCAAA;EACA,gBFWkC;EEVlC,kBAAA;EACA,YCHW;EDIX,eFQ4B;EAC9B,mBAAA;ACMF;;ADHA;EACE,aAAA;EACA,sBAAA;EACA,SAAA;EACA,aAAA;EACA,kBAAA;EACA,uBAAA;ACMF;;ADFE;EACE,kBAAA;EACA,WAAA;EACA,YAAA;EACA,oBAAA;KAAA,iBAAA;EACA,0BAAA;KAAA,uBAAA;ACKJ;;ADDA;EEnCI,uCAAA;EACA,gBFmCkC;EElClC,kBAAA;EACA,YCHW;EDIX,eFgC4B;ACQhC;ADPE;EErCE,uCAAA;EACA,gBFqCoC;EEpCpC,kBAAA;EACA,YCHW;EDIX,eFkC8B;ACalC;ADVE;EEzCE,uCAAA;EACA,gBFyCoC;EExCpC,kBAAA;EACA,YCHW;EDIX,eFsC8B;ACgBlC;ADbE;EACE,aAAA;EACA,sBAAA;EACA,QAAA;ACeJ;;ADXA;EACE,gBAAA;EErDE,uCAAA;EACA,gBFqDkC;EEpDlC,kBAAA;EACA,YCHW;EDIX,eFkD4B;ACkBhC","file":"publicationSlug.css","sourcesContent":["@import \"./variables\";\n@import \"./mixins\";\n\n.section_publications {\n  margin-top: 20px;\n}\n\n.publication_text_title {\n  @include fonts($defaultColor, 24px, 600);\n  margin-bottom: 20px;\n}\n\n.publication_data {\n  @include fonts($defaultColor, 14px, 400);\n  margin-bottom: 10px;\n}\n\n.publication_link_wrap {\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n  padding: 10px;\n  border-radius: 5px;\n  border: 1px solid $defaultColor;\n}\n\n.publication_img {\n  & img {\n    border-radius: 5px;\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n    object-position: center;\n  }\n}\n\n.publication_text {\n  @include fonts($defaultColor, 14px, 400);\n  & p, li {\n    @include fonts($defaultColor, 14px, 400);\n  }\n\n  :where(h1,h2,h3,h4,h5,h6) {\n    @include fonts($defaultColor, 18px, 600);\n  }\n\n  & ul,ol {\n    display: flex;\n    flex-direction: column;\n    gap: 5px;\n  }\n}\n\n.publication_views {\n  margin-top: 10px;\n  @include fonts($defaultColor, 14px, 400);\n}",".section_publications {\n  margin-top: 20px;\n}\n\n.publication_text_title {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 600;\n  font-style: normal;\n  color: black;\n  font-size: 24px;\n  margin-bottom: 20px;\n}\n\n.publication_data {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n  margin-bottom: 10px;\n}\n\n.publication_link_wrap {\n  display: flex;\n  flex-direction: column;\n  gap: 20px;\n  padding: 10px;\n  border-radius: 5px;\n  border: 1px solid black;\n}\n\n.publication_img img {\n  border-radius: 5px;\n  width: 100%;\n  height: 100%;\n  object-fit: cover;\n  object-position: center;\n}\n\n.publication_text {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n.publication_text p, .publication_text li {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}\n.publication_text :where(h1, h2, h3, h4, h5, h6) {\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 600;\n  font-style: normal;\n  color: black;\n  font-size: 18px;\n}\n.publication_text ul, .publication_text ol {\n  display: flex;\n  flex-direction: column;\n  gap: 5px;\n}\n\n.publication_views {\n  margin-top: 10px;\n  font-family: \"Trebuchet MS\", sans-serif;\n  font-weight: 400;\n  font-style: normal;\n  color: black;\n  font-size: 14px;\n}","@mixin fonts($color,$size,$weight) {\n    font-family: 'Trebuchet MS', sans-serif;\n    font-weight: $weight;\n    font-style: normal;\n    color: $color;\n    font-size: $size;\n}","$mainColor: #3077a0;\n$defaultColor: black;\n$colorHover: red;\n$headerTopBorder: #bdd4e2;\n$buttonBg:linear-gradient(0deg, #4d95d6,#6e93dd,#c2d6f4);;\n$gray: #D4D4D4;\n$vipBg: #ff6163;\n$activeItem: #FFFFCA;\n$userSearchBg: #CFE6FE;\n$asideLinksColor: #307792;\n$asideExitColor: rgb(0, 128, 0);"]}2;\n$asideExitColor: rgb(0, 128, 0);"]}